// FreeLang Runtime Core - Memory Management
// First-Fit Free-List 힙 할당자
// Zero-Dependency implementation

// 에러 코드
const RT_ERR_OK:      i32 = 0;
const RT_ERR_OOM:     i32 = 200;    // Out of Memory
const RT_ERR_INVALID: i32 = 201;    // Invalid pointer
const RT_ERR_BOUNDS:  i32 = 202;    // Out of bounds

// 힙 설정
const HEAP_SIZE:       u32 = 65536;   // 64KB
const MAX_HEAP_BLOCKS: i32 = 512;
const ALIGN:           u32 = 8;       // 8-byte alignment

// 힙 블록 메타데이터
struct HeapBlock {
    ptr:    u64;      // 블록 시작 주소
    size:   u32;      // 블록 크기 (바이트)
    used:   bool;     // 사용 중 여부
}

// 전역 상태
let g_heap:        [HeapBlock] = make([HeapBlock], MAX_HEAP_BLOCKS);
let g_heap_base:   u64 = 0;
let g_heap_size:   u32 = 0;
let g_heap_count:  i32 = 0;        // 할당된 블록 수
let g_heap_inited: bool = false;

// 힙 초기화
func rt_init_heap() -> i32 {
    if g_heap_inited {
        return RT_ERR_OK;
    }

    // 초기 메모리 할당 (virtual_alloc 사용)
    let base, err = virtual_alloc(HEAP_SIZE);
    if err != RT_ERR_OK {
        return err;
    }

    g_heap_base = base;
    g_heap_size = 0;
    g_heap_count = 0;

    // 전체 메모리를 하나의 free 블록으로 시작
    let block = HeapBlock {
        ptr: g_heap_base,
        size: HEAP_SIZE,
        used: false,
    };

    g_heap[0] = block;
    g_heap_count = 1;
    g_heap_inited = true;

    return RT_ERR_OK;
}

// 정렬된 할당 크기 계산
@inline
func rt_align_up(size: u32) -> u32 {
    return ((size + ALIGN - 1) / ALIGN) * ALIGN;
}

// First-Fit 메모리 할당
func rt_malloc(size: u32) -> (u64, i32) {
    if !g_heap_inited {
        let init_err = rt_init_heap();
        if init_err != RT_ERR_OK {
            return (0, init_err);
        }
    }

    if size == 0 {
        return (0, RT_ERR_INVALID);
    }

    let aligned_size = rt_align_up(size);
    let i = 0;

    // First-Fit: 첫 번째 적합 블록 찾기
    for i = 0; i < g_heap_count; i = i + 1 {
        let block = g_heap[i];

        if !block.used && block.size >= aligned_size {
            // 찾음: 블록을 분할하고 할당
            let user_ptr = block.ptr;

            // 블록 크기 초과 검사
            if block.size > aligned_size {
                // 남은 부분을 새로운 free 블록으로 생성
                if g_heap_count >= MAX_HEAP_BLOCKS {
                    return (0, RT_ERR_OOM);
                }

                // 블록 배열을 뒤로 시프트
                let j = g_heap_count;
                for j = g_heap_count; j > i + 1; j = j - 1 {
                    g_heap[j] = g_heap[j - 1];
                }

                // 남은 블록 생성
                let remaining_size = block.size - aligned_size;
                let remaining_block = HeapBlock {
                    ptr: user_ptr + u64(aligned_size),
                    size: remaining_size,
                    used: false,
                };
                g_heap[i + 1] = remaining_block;
                g_heap_count = g_heap_count + 1;
            }

            // 요청한 블록 표시
            let used_block = HeapBlock {
                ptr: user_ptr,
                size: aligned_size,
                used: true,
            };
            g_heap[i] = used_block;
            g_heap_size = g_heap_size + aligned_size;

            return (user_ptr, RT_ERR_OK);
        }
    }

    // 적합 블록 없음
    return (0, RT_ERR_OOM);
}

// 메모리 해제 + 블록 병합
func rt_free(ptr: u64) -> i32 {
    if !g_heap_inited {
        return RT_ERR_INVALID;
    }

    if ptr == 0 {
        return RT_ERR_INVALID;
    }

    let i = 0;
    let found_idx = -1;

    // 포인터에 해당하는 블록 찾기
    for i = 0; i < g_heap_count; i = i + 1 {
        if g_heap[i].ptr == ptr {
            found_idx = i;
        }
    }

    if found_idx < 0 {
        return RT_ERR_INVALID;
    }

    // 블록을 free로 표시
    let block = g_heap[found_idx];
    let freed_block = HeapBlock {
        ptr: block.ptr,
        size: block.size,
        used: false,
    };
    g_heap[found_idx] = freed_block;
    g_heap_size = g_heap_size - block.size;

    // 이전 블록이 free이면 병합
    if found_idx > 0 {
        let prev = g_heap[found_idx - 1];
        if !prev.used {
            // 병합: 이전 블록 확장
            let merged = HeapBlock {
                ptr: prev.ptr,
                size: prev.size + block.size,
                used: false,
            };
            g_heap[found_idx - 1] = merged;

            // 현재 블록 제거 (배열 시프트)
            let j = found_idx;
            for j = found_idx; j < g_heap_count - 1; j = j + 1 {
                g_heap[j] = g_heap[j + 1];
            }
            g_heap_count = g_heap_count - 1;

            // found_idx 감소 (이전 블록으로 포인터 이동)
            found_idx = found_idx - 1;
        }
    }

    // 다음 블록이 free이면 병합
    if found_idx < g_heap_count - 1 {
        let next = g_heap[found_idx + 1];
        if !next.used {
            // 병합: 현재 블록 확장
            let merged = HeapBlock {
                ptr: g_heap[found_idx].ptr,
                size: g_heap[found_idx].size + next.size,
                used: false,
            };
            g_heap[found_idx] = merged;

            // 다음 블록 제거 (배열 시프트)
            let j = found_idx + 1;
            for j = found_idx + 1; j < g_heap_count - 1; j = j + 1 {
                g_heap[j] = g_heap[j + 1];
            }
            g_heap_count = g_heap_count - 1;
        }
    }

    return RT_ERR_OK;
}

// 힙 통계
func rt_heap_stats() -> (u32, u32, u32) {
    let total = g_heap_size;
    let free = HEAP_SIZE - g_heap_size;
