	ifNode.Children = append(ifNode.Children, cond)

	if p.curToken.Type != ast.TokenLBrace {
		return nil, fmt.Errorf("expected '{' after if condition")
	}

	body, err := p.parseBlockStmt()
	if err != nil {
		return nil, err
	}

